from io import BytesIO

def baca_identitas(client):
    # Perintah tetap untuk VM Linux lab; bukan perintah universal semua router.
    stdin,stdout,stderr=client.exec_command('uname -s',timeout=3)
    try:
        raw=stdout.read(257);error=stderr.read(257)
        if len(raw)>256 or error:raise ValueError('Respons SSH tidak sesuai batas lab.')
        if stdout.channel.recv_exit_status()!=0:raise ValueError('Perintah gagal.')
        return raw.decode('utf-8').strip()
    finally:
        stdin.close();stdout.close();stderr.close()

def hubungkan_lab(host,port,username,key_filename,known_hosts):
    if host not in {'127.0.0.1','::1'} or type(port) is not int or not 1<=port<=65535:
        raise ValueError('Hanya endpoint loopback lab yang ditentukan.')
    import paramiko  # Dependensi opsional, diperlukan saat koneksi nyata.
    with paramiko.SSHClient() as client:
        client.load_host_keys(known_hosts)
        client.set_missing_host_key_policy(paramiko.RejectPolicy())
        client.connect(hostname=host,port=port,username=username,key_filename=key_filename,
                       allow_agent=False,look_for_keys=False,timeout=3,banner_timeout=3,auth_timeout=3)
        return baca_identitas(client)

class SSHSimulasi:
    def exec_command(self,command,timeout):
        assert command=='uname -s' and timeout==3
        output=BytesIO(b'Linux\n')
        output.channel=type('Channel',(),{'recv_exit_status':lambda self:0})()
        return BytesIO(),output,BytesIO()

if __name__=='__main__':
    print('Identitas simulasi:',baca_identitas(SSHSimulasi()))
    print('Tidak membuka koneksi SSH; host key lab nyata wajib diverifikasi')

import json
from urllib.request import build_opener,ProxyHandler
from lab_web import server_lab

def baca_api(root):
    opener=build_opener(ProxyHandler({}))
    with opener.open(root+'/api/observasi',timeout=2) as response:
        if response.headers.get_content_type()!='application/json':raise ValueError('Butuh JSON.')
        raw=response.read(4097)
        if len(raw)>4096:raise ValueError('Respons melebihi batas.')
        data=json.loads(raw)
        if not isinstance(data,list) or any(not isinstance(x,dict) or set(x)!={'id','layanan','hasil'} for x in data):
            raise ValueError('Skema daftar tidak sesuai.')
        if any(type(x['id']) is not int or x['id']<1 or not isinstance(x['layanan'],str) or not x['layanan'].strip() or len(x['layanan'])>40 or x['hasil'] not in ('ok','timeout','refused') for x in data):raise ValueError('Nilai respons tidak sesuai.')
        return data

if __name__=='__main__':
    with server_lab() as root:
        print('Observasi dari API lokal:',len(baca_api(root)))
    print('Koneksi HTTP benar-benar terjadi pada loopback')

# Varbind yang SUDAH didekode; bukan implementasi paket SNMP atau polling langsung.
SYSNAME='1.3.6.1.2.1.1.5.0'
OPER='1.3.6.1.2.1.2.2.1.8.1'

def ringkas_varbind(varbinds):
    mapping={row['oid']:row for row in varbinds}
    if len(mapping)!=len(varbinds):raise ValueError('OID ganda perlu ditinjau.')
    name,status=mapping[SYSNAME],mapping[OPER]
    if name['type']!='OctetString' or not isinstance(name['value'],str):raise ValueError('Tipe sysName salah.')
    if status['type']!='Integer' or type(status['value']) is not int:raise ValueError('Tipe status salah.')
    return {'nama':name['value'],'status':{1:'up',2:'down'}.get(status['value'],'lainnya')}

def delta_counter32(before,after,uptime_before,uptime_after):
    if any(type(x) is not int or not 0<=x<2**32 for x in [before,after,uptime_before,uptime_after]):raise ValueError('Butuh Counter32.')
    if uptime_after<uptime_before:return None
    return (after-before)%(2**32)  # Asumsi maksimum satu wrap dan tidak ada reset tersembunyi.

if __name__=='__main__':
    rows=[{'oid':SYSNAME,'type':'OctetString','value':'BTS-LAB'},{'oid':OPER,'type':'Integer','value':1}]
    print('Varbind fiktif:',ringkas_varbind(rows))
    print('Delta dengan asumsi satu wrap:',delta_counter32(2**32-6,4,100,110))
    print('Uptime turun, delta:',delta_counter32(10,20,100,5))
    print('Tidak mengirim SNMP GET atau WALK')

def pembuat_batas(minimum):
    def memenuhi(nilai):
        return nilai>=minimum
    return memenuhi

def pengali_benar():
    return [lambda x,n=n:x*n for n in range(3)]

if __name__=='__main__':
    lulus=pembuat_batas(75)
    print('74/75:',lulus(74),lulus(75))
    print('Binding tiap iterasi:',[fungsi(10) for fungsi in pengali_benar()])

from functools import wraps

def hitung_panggilan(function):
    @wraps(function)
    def wrapper(*args,**kwargs):
        wrapper.calls+=1
        return function(*args,**kwargs)
    wrapper.calls=0
    return wrapper

@hitung_panggilan
def tambah(a:int,b:int)->int:
    """Jumlah dua bilangan."""
    return a+b

if __name__=='__main__':
    print('Hasil:',tambah(2,b=3))
    print('Panggilan:',tambah.calls)
    print('Nama dipertahankan:',tambah.__name__)
    print('Fungsi asli:',tambah.__wrapped__(1,2))

