def greedy(koin,target):
    if type(target) is not int or target<0 or not koin or any(type(x) is not int or x<=0 for x in koin):
        raise ValueError('Koin positif dan target integer nonnegatif.')
    hasil=[];sisa=target
    for nilai in sorted(set(koin),reverse=True):
        jumlah,sisa=divmod(sisa,nilai)
        hasil.extend([nilai]*jumlah)
    return hasil if sisa==0 else None

if __name__=='__main__':
    print('Greedy [1,3,4] untuk 6:',greedy([1,3,4],6))
    print('Solusi lebih sedikit:',[3,3])
    print('Pilihan lokal terbesar tidak selalu optimal global')

def pilih_jumlah(values,target):
    if type(target) is not int or target<0 or any(type(x) is not int or x<=0 for x in values):
        raise ValueError('Bilangan positif dan target nonnegatif.')
    if len(values)>16:raise ValueError('Batas eksplorasi lab 16 elemen.')
    hasil=[]
    def cari(index,total,pilihan):
        if total==target:
            hasil.append(pilihan.copy());return
        if total>target or index==len(values):return
        pilihan.append(values[index]);cari(index+1,total+values[index],pilihan);pilihan.pop()
        cari(index+1,total,pilihan)
    cari(0,0,[])
    return hasil

if __name__=='__main__':
    print('Subset untuk 5:',pilih_jumlah([2,3,5],5))
    print('Input dipakai paling banyak sekali per indeks')

def minimum_koin(koin,target):
    if type(target) is not int or not 0<=target<=10000 or not koin or any(type(x) is not int or x<=0 for x in koin):
        raise ValueError('Koin positif, target 0..10000.')
    dp=[None]*(target+1);dp[0]=0
    for total in range(1,target+1):
        kandidat=[dp[total-k]+1 for k in set(koin) if k<=total and dp[total-k] is not None]
        dp[total]=min(kandidat) if kandidat else None
    return dp[target]

if __name__=='__main__':
    print('Minimum untuk 6:',minimum_koin([1,3,4],6))
    print('Tidak terjangkau:',minimum_koin([4],6))
    print('Target nol:',minimum_koin([1,3,4],0))

