from collections import OrderedDict
from time import monotonic
import math

class CacheTTL:
    def __init__(self,capacity=2,clock=monotonic):
        if type(capacity) is not int or capacity<1:raise ValueError('Kapasitas positif.')
        self.capacity=capacity;self.clock=clock;self.data=OrderedDict()
    def put(self,key,value,ttl):
        if not isinstance(ttl,(int,float)) or isinstance(ttl,bool) or not math.isfinite(ttl) or ttl<=0:raise ValueError('TTL finite positif.')
        if value is None:raise ValueError('None dipakai sebagai tanda cache miss.')
        now=self.clock()
        for old in list(self.data):
            if self.data[old][0]<=now:self.data.pop(old)
        self.data[key]=(now+ttl,value);self.data.move_to_end(key)
        while len(self.data)>self.capacity:self.data.popitem(last=False)
    def get(self,key):
        if key not in self.data:return None
        end,value=self.data[key]
        if end<=self.clock():self.data.pop(key);return None
        self.data.move_to_end(key);return value
    def invalidate(self,key):self.data.pop(key,None)

if __name__=='__main__':
    now=[0.0];cache=CacheTTL(clock=lambda:now[0])
    cache.put('status','up',ttl=5)
    print('Sebelum kedaluwarsa:',cache.get('status'))
    now[0]=5
    print('Tepat batas TTL:',cache.get('status'))
    cache.put('status','down',ttl=5);cache.invalidate('status')
    print('Sesudah invalidasi:',cache.get('status'))

from queue import Queue
from threading import Thread

class RetryableError(Exception):pass

def kerjakan(tasks,handler,max_attempts=2):
    if type(max_attempts) is not int or not 1<=max_attempts<=3:raise ValueError('Percobaan 1..3.')
    if len(tasks)>20 or any(not isinstance(t,str) or not t for t in tasks) or len(set(tasks))!=len(tasks):
        raise ValueError('Maksimal 20 ID unik terisi.')
    queue=Queue(maxsize=2);success=[];dead=[]
    def worker():
        while True:
            task=queue.get()
            try:
                if task is None:return
                for attempt in range(1,max_attempts+1):
                    try:
                        handler(task);success.append(task);break
                    except Exception as exc:
                        if not isinstance(exc,RetryableError) or attempt==max_attempts:
                            dead.append({'id':task,'attempts':attempt,'error':type(exc).__name__});break
            finally:queue.task_done()
    thread=Thread(target=worker);thread.start()
    for task in tasks:queue.put(task)
    queue.put(None);queue.join();thread.join()
    return success,dead

if __name__=='__main__':
    attempts={}
    def handler(task):
        attempts[task]=attempts.get(task,0)+1
        if task=='ulang' and attempts[task]==1:raise RetryableError()
        if task=='rusak':raise ValueError('data invalid')
    success,dead=kerjakan(['baik','ulang','rusak'],handler)
    print('Selesai:',success)
    print('Dead letter:',dead)
    print('Percobaan ulang:',attempts['ulang'])
    print('Antrean memori; bukan broker persisten')
